        "{{\"run\":1,\"event\":\"ready\",\"phase\":\"before\",\"node\":5,\"decided\":{},\"entry_status\":\"{}\",\"decided_leader1\":{},\"decided_node2\":{},\"accepted_node2\":{}}}",
