        settle(&mut nodes, &mut q);
    }
    let decided = nodes[0].get_decided_idx();
    let all_accepted_min = nodes
        .iter()
        .map(|n| n.get_accepted_idx())
        .min()
        .unwrap_or(0);
    emit(format!(
        "{{\"run\":3,\"event\":\"setup\",\"nodes\":3,\"pids\":\"1,2,5\",\"decided\":{},\"all_accepted_min\":{}}}",
        decided, all_accepted_min
