    let preparereq_seen = q.iter().any(|m| {
        matches!(m, Message::SequencePaxos(p) if p.to == 2 && matches!(p.msg, PaxosMsg::PrepareReq(_)))
    });
    route(&mut nodes, &mut q, |_| true);
