    collect(&mut nodes, &mut q);
    let promise_seen = q.iter().any(|m| {
        matches!(m, Message::SequencePaxos(p) if p.from == 5 && matches!(p.msg, PaxosMsg::Promise(_)))
    });
    route(&mut nodes, &mut q, |_| true);
    collect(&mut nodes, &mut q);
    let acceptsync_seen = q.iter().any(|m| {
