                nodes: vec![1, 2, 3, 4, 5],
                flexible_quorum: None,
            };
            let _ = nodes[0].reconfigure(next_config, None);
        }
        let choice = next() % 100;
        if choice < 25 && appended < 120 {
            appended += 1;
