    for i in 1..=3u64 {
        nodes[0].append(Value(i)).expect("append failed");
        settle(&mut nodes, &mut q);
    }
    let decided = nodes[0].get_decided_idx();
    let all_accepted_min = nodes
        .iter()
        .map(|n| n.get_accepted_idx())
        .min()
        .unwrap_or(0);
    emit(format!(
