        after_decided < before_decided,
        n5_leader.map(|(_, a)| a).unwrap_or(false),
        nodes[1].get_current_leader().map(|(_, a)| a).unwrap_or(false),
        lost_prepare_count,
        preparereq_seen,
        prepare_seen,
        promise_seen,
        acceptsync_seen,
