        "{{\"run\":10,\"event\":\"safety\",\"appended\":{},\"delivered\":{},\"dropped\":{},\"divergences\":{},\"first_divergence\":\"{}\",\"progressed\":{},\"regressions\":{},\"first_regression\":\"{}\",\"reconfigured\":{},\"decided\":\"{}\"}}",
        appended,
