            nodes[slot].tick();
        } else if !q.is_empty() {
            let idx = (next() as usize) % q.len();
            let m = q.swap_remove(idx);
            if next() % 100 < 20 {
                dropped += 1;
            } else {
                let to = m.get_receiver();
                let slot = nodes.iter().position(|n| n.get_pid() == to).unwrap();
                nodes[slot].handle_incoming(m);
