    emit(format!(
        "{{\"run\":3,\"event\":\"trim_result\",\"requested\":{},\"all_accepted_min\":{},\"trim_ok\":{},\"error_min\":{},\"compacted_after_some\":{},\"none_ok\":{},\"compacted_after_none\":{},\"decided\":{}}}",
        requested,
