    ));
    let ballot = Ballot {
        config_id: 1,
        n: 2,
        priority: 0,
        pid: 9,
    };
    nodes[4].handle_incoming(Message::SequencePaxos(PaxosMessage {
        from: 9,
        to: 5,
        msg: PaxosMsg::Prepare(Prepare {
            n: ballot,
