    emit(format!(
        "{{\"run\":15,\"event\":\"after_sync\",\"accepted\":{},\"decided\":{},\"reconfig\":{},\"k2\":\"{}\",\"k3\":\"{}\"}}",
        nodes[4].get_accepted_idx(),
        nodes[4].get_decided_idx(),
        u8::from(nodes[4].is_reconfigured().is_some()),
