    emit(format!(
        "{{\"run\":16,\"event\":\"ready\",\"accepted\":{},\"decided\":{},\"reconfig\":{}}}",
        nodes[4].get_accepted_idx(),
        nodes[4].get_decided_idx(),
        u8::from(nodes[4].is_reconfigured().is_some())
    ));
    let ballot = Ballot {
        config_id: 1,
        n: 2,
        priority: 0,
        pid: 9,
    };
    nodes[4].handle_incoming(Message::SequencePaxos(PaxosMessage {
        from: 9,
        to: 5,
        msg: PaxosMsg::Prepare(Prepare {
            n: ballot,
            decided_idx: 3,
            n_accepted: Ballot {
                config_id: 1,
                n: 0,
                priority: 0,
                pid: 0,
            },
            accepted_idx: 3,
        }),
    }));
    let log_sync = LogSync {
        decided_snapshot: None,
        suffix: Vec::new(),
        sync_idx: 2,
        stopsign: Some(StopSign::with(next, None)),
    };
    nodes[4].handle_incoming(Message::SequencePaxos(PaxosMessage {
        from: 9,
        to: 5,
        msg: PaxosMsg::AcceptSync(AcceptSync {
            n: ballot,
            seq_num: SequenceNumber {
                session: 1,
                counter: 1,
            },
            decided_idx: 3,
            log_sync,
        }),
    }));
    emit(format!(
        "{{\"run\":16,\"event\":\"after_sync\",\"accepted\":{},\"decided\":{},\"reconfig\":{},\"k2\":\"{}\",\"k3\":\"{}\"}}",
        nodes[4].get_accepted_idx(),
        nodes[4].get_decided_idx(),
        u8::from(nodes[4].is_reconfigured().is_some()),
        entry_status(nodes[4].read(2)),
        entry_status(nodes[4].read(3))
    ));
