    emit(format!(
        "{{\"run\":5,\"event\":\"late_sync\",\"phase\":\"after_sync\",\"node\":5,\"decided\":{},\"accepted\":{},\"decided_before\":5,\"reconfig\":{},\"decided_leader2\":{},\"lost_prepare_count\":{}}}",
