        "{{\"run\":1,\"event\":\"late_sync\",\"phase\":\"after_redecide\",\"node\":5,\"decided\":{},\"entry_status\":\"{}\",\"decided_leader2\":{}}}",
        nodes[4].get_decided_idx(),
        entry_status(nodes[4].read(4)),
        nodes[1].get_decided_idx()
    ));
}

