    }
    let progressed = nodes.iter().any(|n| n.get_decided_idx() > 0);
    emit(format!(
        "{{\"run\":7,\"event\":\"safety\",\"appended\":{},\"delivered\":{},\"dropped\":{},\"divergences\":{},\"first_divergence\":\"{}\",\"progressed\":{},\"decided\":\"{}\"}}",
        appended,
