        }
        collect(&mut nodes, &mut q);
        route(&mut nodes, &mut q, |_| true);
    }
    let progressed = nodes.iter().any(|n| n.get_decided_idx() > 0);
    emit(format!(
        "{{\"run\":8,\"event\":\"safety\",\"appended\":{},\"delivered\":{},\"dropped\":{},\"divergences\":{},\"first_divergence\":\"{}\",\"progressed\":{},\"decided\":\"{}\"}}",
