                nodes[slot].handle_incoming(m);
                delivered += 1;
            }
        }
        collect(&mut nodes, &mut q);
        if q.len() > 4000 {
            let excess = q.len() - 4000;
            q.drain(..excess);
        }
        let prefixes: Vec<Vec<u64>> = nodes.iter().map(decided_values).collect();
