    let mut n5_decide_seq = 0u64;
    let mut n5_prepares = 0usize;
    let mut n5_accsyncs = 0usize;
    let mut n5_stopsigns = 0usize;
    for _ in 0..150 {
        for n in nodes.iter_mut() {
            n.tick();
        }
        collect(&mut nodes, &mut q);
        for m in q.iter() {
            if let Message::SequencePaxos(p) = m {
                if p.to == 5 {
                    match &p.msg {
                        PaxosMsg::Decide(_) => {
                            n5_decides += 1;
                            n5_decide_seq = decide_seq(m).unwrap_or(0);
                        }
                        PaxosMsg::Prepare(_) => n5_prepares += 1,
                        PaxosMsg::AcceptSync(_) => n5_accsyncs += 1,
                        PaxosMsg::AcceptStopSign(_) => n5_stopsigns += 1,
                        _ => {}
                    }
                }
            }
        }
        route(&mut nodes, &mut q, |_| true);
    }
    let n5 = &nodes[4];
    let leader = n5.get_current_leader();
    emit(format!(
        "{{\"run\":14,\"event\":\"after_resend\",\"n5_accepted\":{},\"n5_decided\":{},\"n5_leader_pid\":{},\"n5_accept\":{},\"n5_promise_n\":{},\"leader_decided\":{},\"decision_gap\":{},\"n5_decides\":{},\"n5_decide_seq\":{},\"n5_prepares\":{},\"n5_accsyncs\":{},\"n5_stopsigns\":{},\"decided\":\"{}\"}}",
        n5.get_accepted_idx(),
        n5.get_decided_idx(),
        leader.map(|(p, _)| p).unwrap_or(0),
        leader.map(|(_, a)| a).unwrap_or(false),
        n5.get_promise().n,
        leader_decided,
        leader_decided - n5.get_decided_idx(),
        n5_decides,
        n5_decide_seq,
        n5_prepares,
        n5_accsyncs,
        n5_stopsigns,
        nodes
            .iter()
            .map(|n| n.get_decided_idx().to_string())
            .collect::<Vec<_>>()
            .join(",")
    ));
}

