    collect(&mut nodes, &mut q);
    route(&mut nodes, &mut q, |_| true);
    collect(&mut nodes, &mut q);
    route(&mut nodes, &mut q, |_| true);
    collect(&mut nodes, &mut q);
    route(&mut nodes, &mut q, |_| true);

