                        format!("node {}: {} -> {}", slot + 1, max_decided[slot], d);
                }
            } else {
                max_decided[slot] = d;
            }
        }
    }

    // Fair-delivery convergence: deliver everything and tick every node so the
    // messy history can still reach decisions before the agreement check.
    for _ in 0..150 {
        collect(&mut nodes, &mut q);
