        state ^= state << 17;
        state
    };
    emit("{\"run\":6,\"event\":\"setup_start\",\"nodes\":5,\"actions\":900}".to_string());
    let mut appended = 0u64;
    let mut delivered = 0u64;
    let mut dropped = 0u64;
    let mut divergences = 0u64;
