            let d: Vec<usize> = nodes.iter().map(|n| n.get_decided_idx()).collect();
            if q.is_empty() && d[0] > 0 && d.iter().all(|x| *x == d[0]) {
                break;
            }
        }
        for m in q.iter() {
            if m.get_sender() == 3 {
                match msg_tag(m).as_str() {
