    let held_acks = extract(&mut q, |m| {
        matches!(m, Message::SequencePaxos(p) if (p.from == 3 || p.from == 4) && matches!(p.msg, PaxosMsg::Accepted(_)))
    });
    nodes[4].reconnected(2);
