        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    emit("{\"run\":13,\"event\":\"setup_start\",\"nodes\":5,\"actions\":900}".to_string());
    let mut appended = 0u64;
