#[test]
fn lost_prepare_reconnect_regresses_decided() {
    let mut nodes: Vec<Node> = (1..=5).map(build_node).collect();
    let mut q: Vec<Message<Value>> = Vec::new();
    settle(&mut nodes, &mut q);
