        "{{\"run\":5,\"event\":\"late_sync\",\"phase\":\"after_redecide\",\"node\":5,\"decided\":{},\"accepted\":{},\"reconfig\":{},\"decided_leader2\":{}}}",
        nodes[4].get_decided_idx(),
        nodes[4].get_accepted_idx(),
