        }
        collect(&mut nodes, &mut q);
        let a4 = nodes[3].get_accepted_idx();
        if a4 != p4_last_accepted && p4_acc_changes.len() < 20 {
            p4_acc_changes.push(format!("{step}:{}->{}", p4_last_accepted, a4));
            p4_last_accepted = a4;
        }
        if q.len() > 4000 {
            let excess = q.len() - 4000;
            q.drain(..excess);
