            p4_last_accepted = a4;
        }
    }
    let progressed = nodes.iter().any(|n| n.get_decided_idx() > 0);
    let reconfigured = nodes.iter().any(|n| n.is_reconfigured().is_some());
    emit(format!(
        "{{\"run\":13,\"event\":\"safety\",\"appended\":{},\"delivered\":{},\"dropped\":{},\"divergences\":{},\"first_divergence\":\"{}\",\"progressed\":{},\"regressions\":{},\"first_regression\":\"{}\",\"reconfigured\":{},\"converged_all\":{},\"rounds_run\":{},\"n3_accepted\":{},\"n3_decided\":{},\"n3_leader_pid\":{},\"n3_accept\":{},\"n3_promise_n\":{},\"n3_accepted_changes\":{},\"n3_prepreq\":{},\"n3_promise_sent\":{},\"n3_reconfig\":{},\"n4_reconfig\":{},\"n3_k35\":\"{}\",\"n3_k36\":\"{}\",\"n3_k37\":\"{}\",\"n4_k35\":\"{}\",\"n4_k36\":\"{}\",\"n4_k37\":\"{}\",\"n1_accepted\":{},\"n1_decided\":{},\"n1_k37\":\"{}\",\"n2_accepted\":{},\"n2_decided\":{},\"n2_k37\":\"{}\",\"n5_accepted\":{},\"n5_decided\":{},\"n5_k37\":\"{}\",\"n3_trace\":\"{}\",\"p4_accepted\":{},\"p4_decided\":{},\"p4_gap\":{},\"p4_promises\":\"{}\",\"p4_acc_changes\":\"{}\",\"decided\":\"{}\"}}",
