            let _ = nodes[0].reconfigure(next_config, None);
        }
        let choice = next() % 100;
        if choice < 25 && appended < 120 {
            appended += 1;
            let slot = (next() % 5) as usize;
            if nodes[slot].append(Value(appended)).is_err() {
                appended -= 1;
            }
        } else if choice < 45 {
            let slot = (next() % 5) as usize;
            nodes[slot].tick();
        } else if !q.is_empty() {
