    );
    emit(format!(
        "{{\"run\":15,\"event\":\"before_sync\",\"accepted\":{},\"decided\":{},\"reconfig\":{},\"k2\":\"{}\",\"k3\":\"{}\"}}",
        before.0,
        before.1,
        u8::from(before.2),
        entry_status(nodes[4].read(2)),
        entry_status(nodes[4].read(3))
