        }),
    }));
    let log_sync = LogSync {
        decided_snapshot: None,
        suffix: Vec::new(),
        sync_idx: 3,
        stopsign: Some(StopSign::with(next, None)),
    };
    nodes[4].handle_incoming(Message::SequencePaxos(PaxosMessage {
        from: 9,
        to: 5,
        msg: PaxosMsg::AcceptSync(AcceptSync {
            n: ballot,
            seq_num: SequenceNumber {
