    storage
        .set_stopsign(Some(StopSign::with(next, None)))
        .expect("set_stopsign failed");
    storage.set_decided_idx(4).expect("set_decided_idx failed");
    emit(format!(
        "{{\"run\":17,\"event\":\"stored\",\"log_len\":{},\"decided\":{},\"stopsign\":{}}}",
